@Tags(['slow'])
library;

import 'dart:async';
import 'dart:math';

import 'package:harbor/src/media/intra_pred_row.dart';
import 'package:rohd/rohd.dart';
import 'package:test/test.dart';

// Row-sequential intra predictor at bs=64 (all 13 modes) vs the SW golden, row
// by row. Reduced vectors (2 iters, 2 availability combos) to bound sim time.
void main() {
  tearDown(() async {
    await Simulator.reset();
  });

  const bs = 64;
  test(
    'HarborIntraPredRow bs=64 all modes match predictIntraRaw',
    timeout: const Timeout(Duration(minutes: 25)),
    () async {
      final rowBits = (bs - 1).bitLength;
      final t = HarborIntraPredRow(bs: bs);
      final clk = SimpleClockGenerator(10).clk;
      final mode = Logic(name: 'mode', width: 4);
      final haveA = Logic(name: 'have_above');
      final haveL = Logic(name: 'have_left');
      final above = Logic(name: 'above', width: bs * 8);
      final left = Logic(name: 'left', width: bs * 8);
      final corner = Logic(name: 'above_left', width: 8);
      final row = Logic(name: 'row', width: rowBits);
      t.input('mode').srcConnection! <= mode;
      t.input('have_above').srcConnection! <= haveA;
      t.input('have_left').srcConnection! <= haveL;
      t.input('above').srcConnection! <= above;
      t.input('left').srcConnection! <= left;
      t.input('above_left').srcConnection! <= corner;
      t.input('row').srcConnection! <= row;
      await t.build();
      Simulator.setMaxSimTime(2000000000);
      unawaited(Simulator.run());

      BigInt packB(List<int> b) {
        var v = BigInt.zero;
        for (var i = 0; i < b.length; i++) {
          v |= BigInt.from(b[i] & 0xff) << (i * 8);
        }
        return v;
      }

      var gi = 0;
      final rng = Random(0x64ABC);
      for (var iter = 0; iter < 2; iter++) {
        final av = [for (var i = 0; i < bs; i++) rng.nextInt(256)];
        final lf = [for (var i = 0; i < bs; i++) rng.nextInt(256)];
        final cr = rng.nextInt(256);
        for (var m = 0; m < 13; m++) {
          for (final combo in const [
            [1, 1],
            [0, 0],
          ]) {
            final av0 = combo[0], lv0 = combo[1];
            final want = _goldenRow64.sublist(gi * bs * bs, (gi + 1) * bs * bs);
            gi++;
            for (var r = 0; r < bs; r++) {
              mode.put(m);
              haveA.put(av0);
              haveL.put(lv0);
              above.put(packB(av));
              left.put(packB(lf));
              corner.put(cr);
              row.put(r);
              await clk.nextPosedge;
              final pv = t.output('pred_row').value.toBigInt();
              final got = [
                for (var c = 0; c < bs; c++)
                  ((pv >> (c * 8)) & BigInt.from(0xff)).toInt(),
              ];
              final wantRow = [for (var c = 0; c < bs; c++) want[r * bs + c]];
              expect(
                got,
                equals(wantRow),
                reason: 'bs=64 mode=$m haveA=$av0 haveL=$lv0 row=$r',
              );
            }
          }
        }
      }
      await Simulator.endSimulation();
    },
  );
}

